function isUnpinnedBaseImage(fromLine) {
  // fromLine looks like "FROM node:20.11-bookworm-slim" or "FROM node"
  // or "FROM node@sha256:abcd..."
  // TODO: return true if it's unpinned (latest, or no tag at all),
  // false if it has a specific tag or a digest pin
}

items.solution:
function isUnpinnedBaseImage(fromLine) {
  const match = fromLine.match(/^FROM\s+(\S+)/i);
  if (!match) return false;
  const imageRef = match[1];
  if (imageRef.includes('@sha256:')) return false;
  const afterRegistry = imageRef.split('/').pop();
  if (!afterRegistry.includes(':')) return true;
  return afterRegistry.endsWith(':latest');
}

